<map version="1.0.1"><node CREATED="1747229453204" ID="ID_root" MODIFIED="1747229453204" TEXT="进程基础"><node CREATED="1747229453204" ID="ID_bdf254f86775548c" POSITION="right" MODIFIED="1747229453204" TEXT="进程是什么"><node CREATED="1747229453204" ID="ID_92585189c816f72b" MODIFIED="1747229453204" TEXT="进程是运行起来的程序。如果只是安装了程序，这个程序不叫进程。&amp;nbsp;只有这些文件运行起来的时候才叫做进程&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229453204" ID="ID_cfa9ef60ecd2bc51" POSITION="right" MODIFIED="1747229453204" TEXT="虚拟"><node CREATED="1747229453204" ID="ID_151f47b372da8c65" MODIFIED="1747229453204" TEXT="虚拟内存：&amp;nbsp;我们认为我们占用的内存，是一块连续的，从0开始的内存。&amp;nbsp;&amp;lt;br&amp;gt;"><node CREATED="1747229453204" ID="ID_4b5bda5a665618d4" MODIFIED="1747229453204" TEXT="虚拟内存到真实内存。&amp;lt;br&amp;gt;操作系统在底层做映射&amp;nbsp;"></node></node><node CREATED="1747229453204" ID="ID_46ef48f7e1ea9bb1" MODIFIED="1747229453204" TEXT="虚拟CPU：&amp;nbsp;我们认为，我们的程序在运行的时候，就一个人拥有这个CPU"></node><node CREATED="1747229453204" ID="ID_b43c9f678fb71f83" MODIFIED="1747229453204" TEXT="虚拟文件系统：&amp;nbsp;盘有很多，存储方式，数据组织方式都不相同，但是对于上层使用者，不想关心这些细节，只需要知道路径。&amp;nbsp;&amp;lt;br&amp;gt;至于这个路径的内存实际存储在盘的哪个位置，"></node></node><node CREATED="1747229453204" ID="ID_443bfb8b0cced6f1" POSITION="right" MODIFIED="1747229453204" TEXT="进程"><node CREATED="1747229453204" ID="ID_70c0ff73ed2c9f01" MODIFIED="1747229453204" TEXT="进程状态要了解一下"><node CREATED="1747229453204" ID="ID_d6168f2d9dd2eb85" MODIFIED="1747229453204" TEXT="运行态、就绪、等待"></node></node><node CREATED="1747229453204" ID="ID_8bf6495b253dd6ea" MODIFIED="1747229453204" TEXT="进程的调度"><node CREATED="1747229453204" ID="ID_7f7f4969122e2384" MODIFIED="1747229453204" TEXT="CPU的时间是比较宝贵的。所以，它采用的方式，是将自己的时间划成一个个的时间片，你要占用CPU，就来&amp;lt;br&amp;gt;抢这个时间片。&amp;nbsp;&amp;lt;br&amp;gt;得到这个时间片，才能运行"></node><node CREATED="1747229453204" ID="ID_0702d772d7c6911e" MODIFIED="1747229453204" TEXT="CPU的调度策略，了解一下。&amp;nbsp;&amp;lt;br&amp;gt;现在的操作系统中，一般是组合的调度策略&amp;lt;br&amp;gt;"></node><node CREATED="1747229453204" ID="ID_ef379fadded3d54a" MODIFIED="1747229453204" TEXT="我们就认为，是抢的。谁抢到就执行谁。"><node CREATED="1747229453204" ID="ID_84f454dfe7535d28" MODIFIED="1747229453204" TEXT="会哭的孩子有奶吃。&amp;nbsp;"></node></node></node><node CREATED="1747229453204" ID="ID_c4321ffc0664e31d" MODIFIED="1747229453204" TEXT="进程其实是需要保存自己的信息的"><node CREATED="1747229453204" ID="ID_4a2273e5e82bbb0e" MODIFIED="1747229453204" TEXT="内存"></node><node CREATED="1747229453204" ID="ID_c9ecce001eadc9de" MODIFIED="1747229453204" TEXT="PCB: Process Control Block&amp;lt;br&amp;gt;逻辑概念。"></node><node CREATED="1747229453204" ID="ID_43b22736c6610964" MODIFIED="1747229453204" TEXT="在Linux里面，其实是使用的结构体保存自己的信息。&amp;lt;br&amp;gt;task_struct&amp;lt;br&amp;gt;"></node></node></node><node CREATED="1747229453204" ID="ID_6e3eb574be80e712" POSITION="right" MODIFIED="1747229453204" TEXT="进程相关shell命令"><node CREATED="1747229453204" ID="ID_bb1256b2092c34cb" MODIFIED="1747229453204" TEXT="shell命令，简单说就是在Linux上，使用命令看进程状态"></node><node CREATED="1747229453204" ID="ID_db2bad495e466b6f" MODIFIED="1747229453204" TEXT="ps命令"><node CREATED="1747229453204" ID="ID_000516382450f228" MODIFIED="1747229453204" TEXT="ps就是查看有哪些进程。常见的是两个&amp;nbsp;&amp;lt;br&amp;gt;ps -elf&amp;nbsp; 进程id。状态，开始时间&amp;lt;br&amp;gt;ps aux&amp;lt;br&amp;gt;这两个选项的输出，建议大家把输出的含义记一下"></node><node CREATED="1747229453204" ID="ID_3fd830556cea9fe3" MODIFIED="1747229453204" TEXT="ps -elf中比较重要的"><node CREATED="1747229453204" ID="ID_71aca4a7c07dc629" MODIFIED="1747229453204" TEXT="S（状态）：&amp;nbsp;进程的状态。 R运行中，S睡眠。&amp;lt;br&amp;gt;大部分的进程基本都是睡眠。&amp;lt;br&amp;gt;Z叫做僵尸进程。如果出现了僵尸进程，需要注意&amp;lt;br&amp;gt;"></node><node CREATED="1747229453204" ID="ID_b07daebfd9671d0e" MODIFIED="1747229453204" TEXT="PID(进程id)，&amp;nbsp;用来唯一标识这个进程的。&amp;nbsp;&amp;lt;br&amp;gt;这个是一个关键属性。后续的很多操作，都需要用到pid&amp;lt;br&amp;gt;"><node CREATED="1747229453204" ID="ID_1561712195475e95" MODIFIED="1747229453204" TEXT="getpid()&amp;lt;br&amp;gt;getppid();"></node></node><node CREATED="1747229453204" ID="ID_6da25e2476962fab" MODIFIED="1747229453204" TEXT="PPID(进程的父id)。&amp;nbsp;进程是被另外的进程创建出来的，这时候里面存储就是进程的父id"></node><node CREATED="1747229453204" ID="ID_a143c8a92d86f6df" MODIFIED="1747229453204" TEXT="C(CPU使用率)：&amp;nbsp;如果C过高，说明这个进程占用CPU比较多。&amp;nbsp;"></node><node CREATED="1747229453204" ID="ID_9a17a22c92a8cdaa" MODIFIED="1747229453204" TEXT="PRI/NI:&amp;nbsp;优先级，进程的优先级。&amp;nbsp;我们没有办法直接改优先级，只能改NI，来控制优先级"><node CREATED="1747229453204" ID="ID_28e6487c0e651767" MODIFIED="1747229453204" TEXT="这个值，只对系统有建议。&amp;nbsp;但是不构成强制"></node></node><node CREATED="1747229453204" ID="ID_d1005d6a53eff983" MODIFIED="1747229453204" TEXT="SZ(内存使用大小)：&amp;nbsp;显示当前进程使用了多少内存。"></node><node CREATED="1747229453204" ID="ID_b078928ef0fa899c" MODIFIED="1747229453204" TEXT="STIME:&amp;nbsp;开始时间，进程从什么时候开始跑起来的。这个对于了解一个进程的启动时间比较关键&amp;lt;br&amp;gt;"><node CREATED="1747229453204" ID="ID_9deac8384559f4c1" MODIFIED="1747229453204" TEXT="一般就是观察，程序的启动时间。&amp;nbsp;&amp;lt;br&amp;gt;看一下程序有没有被偷偷关掉过。&amp;nbsp;&amp;nbsp;"></node></node><node CREATED="1747229453204" ID="ID_c93cd00cc1a78a77" MODIFIED="1747229453204" TEXT="TIME（占用了多少CPU时间）：&amp;nbsp;这个程序被CPU运行了多久"></node><node CREATED="1747229453204" ID="ID_9d89cbe6d838a584" MODIFIED="1747229453204" TEXT="CMD：&amp;nbsp;启动进程的命令&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229453204" ID="ID_1f275901dc988be1" MODIFIED="1747229453204" TEXT="ps aux"><node CREATED="1747229453204" ID="ID_9a8b143b0be61006" MODIFIED="1747229453204" TEXT="PID"></node><node CREATED="1747229453204" ID="ID_99e38839548395ce" MODIFIED="1747229453204" TEXT="%MEM/%CPU"><node CREATED="1747229453204" ID="ID_8d145b45a3e3ae3f" MODIFIED="1747229453204" TEXT="主要就是看CPU的占用，和内存的占用&amp;lt;br&amp;gt;如果电脑比较慢了，可以看这俩"></node></node><node CREATED="1747229453204" ID="ID_798b215d258fdd6c" MODIFIED="1747229453204" TEXT="VSZ"><node CREATED="1747229453204" ID="ID_345f208c46d396ab" MODIFIED="1747229453204" TEXT="理论上要占用的虚拟内存大小"></node></node><node CREATED="1747229453204" ID="ID_2749eb6d9622fc80" MODIFIED="1747229453204" TEXT="RSS"><node CREATED="1747229453204" ID="ID_f03191f5fc5791a6" MODIFIED="1747229453204" TEXT="实际占用的内存大小"></node></node><node CREATED="1747229453204" ID="ID_a352229ec137c112" MODIFIED="1747229453204" TEXT="COMMAND"><node CREATED="1747229453204" ID="ID_0017e92c40b8e659" MODIFIED="1747229453204" TEXT="启动的命令"></node></node></node><node CREATED="1747229453204" ID="ID_e6a5c4940a99c464" MODIFIED="1747229453204" TEXT="输出的信息，一些重点的需要知道一下"></node><node CREATED="1747229453204" ID="ID_d08b1d3c3f47f451" MODIFIED="1747229453204" TEXT="因为后续需要观察进程的状态。&amp;nbsp;借此观察电脑的状态"></node><node CREATED="1747229453204" ID="ID_668086caedb4d4f7" MODIFIED="1747229453204" TEXT="比如电脑莫名奇妙开始慢，怎么办？"><node CREATED="1747229453204" ID="ID_3afd9eae6d9c61d4" MODIFIED="1747229453204" TEXT="CPU、内存、磁盘"></node></node></node><node CREATED="1747229453204" ID="ID_bc2600f0e9b82359" MODIFIED="1747229453204" TEXT="free命令"><node CREATED="1747229453204" ID="ID_66e69bf05c168093" MODIFIED="1747229453204" TEXT="要知道一下含义"></node><node CREATED="1747229453204" ID="ID_c3481b63808e183e" MODIFIED="1747229453204" TEXT="free -h"></node><node CREATED="1747229453204" ID="ID_29d46b4d0eb78590" MODIFIED="1747229453204" TEXT="Swap是什么东西要知道一下"></node><node CREATED="1747229453204" ID="ID_dfcf90e1b5edc69e" MODIFIED="1747229453204" TEXT="total:&amp;nbsp;总的内存，一般是看机器的总配置&amp;lt;br&amp;gt;used:&amp;nbsp;使用了的内存。&amp;lt;br&amp;gt;avaiable:&amp;nbsp;系统现在可用的。&amp;nbsp;因为系统在必要的时候，可以将cache踢下线。让这些cache使用的空间被程序使用的&amp;lt;br&amp;gt;swap:&amp;nbsp; 交换区。&amp;nbsp;可以使用磁盘的东西充当内存，这时候速度慢一点。&amp;nbsp;"></node></node><node CREATED="1747229453204" ID="ID_3708ee1641bd4508" MODIFIED="1747229453204" TEXT="top命令"><node CREATED="1747229453204" ID="ID_140e5911d288431c" MODIFIED="1747229453204" TEXT="以概览的方式，显示&amp;nbsp;电脑启动时间、用户数、&amp;lt;br&amp;gt;任务数&amp;lt;br&amp;gt;CPU时间&amp;lt;br&amp;gt;内存"><node CREATED="1747229453204" ID="ID_4c992c8799288617" MODIFIED="1747229453204" TEXT="load average:&amp;nbsp;一定要知道含义"></node></node><node CREATED="1747229453204" ID="ID_02d8d136b855b0ac" MODIFIED="1747229453204" TEXT="更加好看的top。 htop&amp;lt;br&amp;gt;用的时候需要安装一下&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229453204" ID="ID_a1e1850d82fe3306" MODIFIED="1747229453204" TEXT="kill命令"><node CREATED="1747229453204" ID="ID_68eef21707f6af05" MODIFIED="1747229453204" TEXT="杀死一个进程"></node><node CREATED="1747229453204" ID="ID_ff8866573bc23f1c" MODIFIED="1747229453204" TEXT="强制杀。通知一下自己挂&amp;lt;br&amp;gt;kill -2&amp;nbsp;通知一下进程自己挂&amp;lt;br&amp;gt;kill -9&amp;nbsp;强制杀"></node><node CREATED="1747229453204" ID="ID_1157ae8b561e8fa7" MODIFIED="1747229453204" TEXT="kill -9&amp;nbsp;杀。&amp;lt;br&amp;gt;"></node></node></node><node CREATED="1747229453204" ID="ID_6961307ca170c62d" POSITION="right" MODIFIED="1747229453204" TEXT="进程相关函数"><node CREATED="1747229453204" ID="ID_9a7cbd709dc8553d" MODIFIED="1747229453204" TEXT="创建进程"><node CREATED="1747229453204" ID="ID_f773e697890d7cbf" MODIFIED="1747229453204" TEXT="system"><node CREATED="1747229453204" ID="ID_9753076bfeaa7a1f" MODIFIED="1747229453204" TEXT="可以使用system函数，调用其他的程序。其实就相当于启动了另外一个进程"></node><node CREATED="1747229453204" ID="ID_7cfc2cc7393f8826" MODIFIED="1747229453204" TEXT="使用的不多。&amp;nbsp;原因是耗时。&amp;nbsp;"></node><node CREATED="1747229453204" ID="ID_f8427dbee9d7c5a4" MODIFIED="1747229453204" TEXT="ISO-C标准库函数:&amp;nbsp;在其他的系统中都能用。"></node></node><node CREATED="1747229453204" ID="ID_e68a8a9134d67d1e" MODIFIED="1747229453204" TEXT="fork(这个非常重要)"><node CREATED="1747229453204" ID="ID_4b2841dd7adfc416" MODIFIED="1747229453204" TEXT="就是用于创建子进程。&amp;nbsp;&amp;lt;br&amp;gt;pid_t fork(void);"></node><node CREATED="1747229453204" ID="ID_48523a74176c7c51" MODIFIED="1747229453204" TEXT="fork就是创建一个子进程。&amp;nbsp;父子进程，会执行fork函数下的所有代码。&amp;nbsp;"></node><node CREATED="1747229453204" ID="ID_7ba7fc1e0d84cebf" MODIFIED="1747229453204" TEXT="主要是依靠fork函数的返回值来确认，当前进程是父进程，还是子进程"><node CREATED="1747229453204" ID="ID_ce331fde1c518177" MODIFIED="1747229453204" TEXT="返回值如果是正数，&amp;nbsp;说明是父进程。&amp;lt;br&amp;gt;返回的值是子进程的pid"></node><node CREATED="1747229453204" ID="ID_d7a4024c46612cca" MODIFIED="1747229453204" TEXT="返回值是0，说明是子进程。&amp;nbsp;"></node></node><node CREATED="1747229453204" ID="ID_2ab2ab7cc8bdfee1" MODIFIED="1747229453204" TEXT="写时复制"><node CREATED="1747229453204" ID="ID_978806c100f33410" MODIFIED="1747229453204" TEXT="刚开始fork的时候，物理内存并不会完整做复制。因为这样，时间花了，内存也花了。&amp;nbsp;效率非常低。&amp;nbsp;&amp;lt;br&amp;gt;所以，刚开始的时候，大家是共享物理内存的。&amp;nbsp;&amp;lt;br&amp;gt;但是一旦一个进程想往里面写数据，这时候再共享就不好了。&amp;nbsp;所以写时复制，意思是，有进程修改，就将这个物理内存复制一份。&amp;nbsp;"></node><node CREATED="1747229453204" ID="ID_bc2032df15424363" MODIFIED="1747229453204" TEXT="复制的单位是页，并不是整个物理内存"></node><node CREATED="1747229453204" ID="ID_7a5cccaf356f8674" MODIFIED="1747229453204" TEXT="是一个优化，&amp;nbsp;如果实在无法理解。&amp;nbsp;fork的时候，数据完全分家。&amp;nbsp;"></node></node></node><node CREATED="1747229453204" ID="ID_ad0ea1adeeb95048" MODIFIED="1747229453204" TEXT="exec函数族"><node CREATED="1747229453204" ID="ID_e8744a4a4aee6392" MODIFIED="1747229453204" TEXT="POSIX-C标准库函数&amp;lt;br&amp;gt;"></node><node CREATED="1747229453204" ID="ID_b461a3afa20bfdf1" MODIFIED="1747229453204" TEXT="使用execl。execv可以在当前进程，调用起其他的进程"></node><node CREATED="1747229453204" ID="ID_3c9fb175656b6cb0" MODIFIED="1747229453204" TEXT="execl，参数是散开的，一个一个给。&amp;nbsp;&amp;lt;br&amp;gt;execv，参数是列表。&amp;nbsp;就是要给一个数组"><node CREATED="1747229453204" ID="ID_1fc7eaab4365d440" MODIFIED="1747229453204" TEXT="注意1：&amp;nbsp;都需要有一个 (char *)0，来标识终止条件"></node><node CREATED="1747229453204" ID="ID_cb4223cd4568dba2" MODIFIED="1747229453204" TEXT="注意2：参数和传统的参数有一些区别。&amp;nbsp;&amp;lt;br&amp;gt;execl(&amp;quot;./test1&amp;quot;, &amp;quot;arg1&amp;quot;, &amp;quot;arg2&amp;quot;, (char *)0);&amp;lt;br&amp;gt;./test1 arg1 arg2&amp;lt;br&amp;gt;传统的参数，第一个是程序名。所以建议使用execl的时候，参数位置第一个写函数名"></node></node></node></node><node CREATED="1747229453204" ID="ID_7ef5a292e34cbe62" MODIFIED="1747229453204" TEXT="退出进程"><node CREATED="1747229453204" ID="ID_d05ef87ee3f7e272" MODIFIED="1747229453204" TEXT="exit"><node CREATED="1747229453204" ID="ID_0326b611ff90a816" MODIFIED="1747229453204" TEXT="这个函数族是退出进程的。&amp;nbsp;要知道它们退出的区别"></node><node CREATED="1747229453204" ID="ID_85a8ac279c1765e3" MODIFIED="1747229453204" TEXT="exit这个函数，会清理io"></node><node CREATED="1747229453204" ID="ID_f9d0d04f0952172c" MODIFIED="1747229453204" TEXT="_Exit和_exit这两个函数，不会清理io"></node></node><node CREATED="1747229453204" ID="ID_eeb7e1a6fa6ccb34" MODIFIED="1747229453204" TEXT="通过信号退出"><node CREATED="1747229453204" ID="ID_b5ca71f42daad9b8" MODIFIED="1747229453204" TEXT="ctrl + c或者 ctrl +\&amp;nbsp;这时候就相当于给进程发一个信号。让它看示意自己挂"></node><node CREATED="1747229453204" ID="ID_905a7aa785bad72c" MODIFIED="1747229453204" TEXT="kill -2&amp;nbsp;pid&amp;nbsp;其实就是给这个pid，发一个2的信号。"></node></node></node><node CREATED="1747229453204" ID="ID_c0af45c213eed23c" MODIFIED="1747229453204" TEXT="进程控制"><node CREATED="1747229453204" ID="ID_fb2a396920f6397e" MODIFIED="1747229453204" TEXT="两种特殊的进程"><node CREATED="1747229453204" ID="ID_de738df49aaf6c84" MODIFIED="1747229453204" TEXT="孤儿进程：&amp;nbsp;就是子进程一直运行，父进程挂了。&amp;nbsp;这时候，这个进程会被pid为1的父进程收养"></node><node CREATED="1747229453204" ID="ID_bf97df743a451a68" MODIFIED="1747229453204" TEXT="僵尸进程：&amp;nbsp;就是父进程一直运行，子进程挂了。&amp;nbsp;这个父进程也没时间替子进程收拾（处理一些资源）。&amp;nbsp;这时候就变成了僵尸进程"></node></node><node CREATED="1747229453204" ID="ID_235a49454973188f" MODIFIED="1747229453204" TEXT="wait"><node CREATED="1747229453204" ID="ID_fd522a531a43728b" MODIFIED="1747229453204" TEXT="父进程等子进程。"></node><node CREATED="1747229453204" ID="ID_6d3feee0a5f5657a" MODIFIED="1747229453204" TEXT="wait就是等一个结束就行。&amp;lt;br&amp;gt;wait函数是阻塞的，也就是没子进程结束，&amp;nbsp;就一直等&amp;nbsp;&amp;lt;br&amp;gt;返回值就是等到的子进程的pid&amp;lt;br&amp;gt;参数里面有子进程的状态"></node><node CREATED="1747229453204" ID="ID_9b2a360399f20008" MODIFIED="1747229453204" TEXT="pid_t wait(int *status);&amp;lt;br&amp;gt;有一些宏定义，可以去status里面，拿到是否是正常退出的；&amp;nbsp;是否是信号量退出的"></node><node CREATED="1747229453204" ID="ID_e07947ab2524940b" MODIFIED="1747229453204" TEXT="参数里面，不光只有状态，有很多信息。&amp;nbsp;比如，程序是不是正常终止的&amp;lt;br&amp;gt;程序是正常终止的，这时候程序的返回码给一下；&amp;lt;br&amp;gt;程序是信号退掉的，信号也可以从这里面拿"></node><node CREATED="1747229453204" ID="ID_a663e62dbf540b4b" MODIFIED="1747229453204" TEXT="随机等一个。&amp;nbsp;"></node></node><node CREATED="1747229453204" ID="ID_bcb9c99b0a3a0545" MODIFIED="1747229453204" TEXT="waitpid"><node CREATED="1747229453204" ID="ID_f2445ba671145c07" MODIFIED="1747229453204" TEXT="pid_t waitpid(&amp;lt;br&amp;gt;&amp;nbsp; &amp;nbsp; pid_t pid,&amp;nbsp; &amp;nbsp; &amp;nbsp; // 指定等待的PID的子进程&amp;lt;br&amp;gt;&amp;nbsp; &amp;nbsp; int *wstatus,&amp;nbsp; &amp;nbsp;// 存储进程的退出状态&amp;lt;br&amp;gt;&amp;nbsp; &amp;nbsp; int options&amp;nbsp; &amp;nbsp; &amp;nbsp;// 修改 waitpid 的行为的选项, 默认0&amp;lt;br&amp;gt;);"></node><node CREATED="1747229453204" ID="ID_3fca6a59faf32ecb" MODIFIED="1747229453204" TEXT="pid"><node CREATED="1747229453204" ID="ID_0b6485760d94f501" MODIFIED="1747229453204" TEXT="可以指定等待的pid。"></node><node CREATED="1747229453204" ID="ID_e907d9963417f4ae" MODIFIED="1747229453204" TEXT="&amp;lt; -1&amp;nbsp;等待进程PID和pid绝对值的进程"></node><node CREATED="1747229453204" ID="ID_6ad8599e6f919ed8" MODIFIED="1747229453204" TEXT="== -1 ：&amp;nbsp;"></node><node CREATED="1747229453204" ID="ID_2235d3d97bda5f64" MODIFIED="1747229453204" TEXT="&amp;gt; 0:&amp;nbsp;等待指定PID的进程"></node></node><node CREATED="1747229453204" ID="ID_5b66167a63be4415" MODIFIED="1747229453204" TEXT="options:&amp;nbsp;可以实现不阻塞的等。&amp;nbsp;这个时候，我们可以用它完成等到60s后，再退出的功能。&amp;nbsp;&amp;nbsp;&amp;lt;br&amp;gt;WNOHANG&amp;lt;br&amp;gt;"></node></node></node><node CREATED="1747229453204" ID="ID_90d6e781d10a0834" MODIFIED="1747229453204" TEXT="守护进程"><node CREATED="1747229453204" ID="ID_673f581e56ee77f3" MODIFIED="1747229453204" TEXT="进程组"><node CREATED="1747229453204" ID="ID_7320c09f244db938" MODIFIED="1747229453204" TEXT="组有什么作用？"><node CREATED="1747229453204" ID="ID_5c2f877e4f1f6829" MODIFIED="1747229453204" TEXT="在系统里面，有组的概念。&amp;nbsp;比如一些用户属于一个组。&amp;nbsp;&amp;lt;br&amp;gt;比如，一些用户有一些权限。如果分别管理这些权限，太麻烦。&amp;lt;br&amp;gt;方便一些权限的分配，和回收。和管理的任务。&amp;nbsp;"></node></node></node><node CREATED="1747229453204" ID="ID_cde0ea415d1203dc" MODIFIED="1747229453204" TEXT="进程组"><node CREATED="1747229453204" ID="ID_aad6ece65f8bcbef" MODIFIED="1747229453204" TEXT="进程不仅属于进程自己，还属于一个进程组。&amp;nbsp;所以不光有进程id，&amp;nbsp;还有进程组id。"></node><node CREATED="1747229453204" ID="ID_e40dad202ad23c18" MODIFIED="1747229453204" TEXT="shell本质属于一个进程，我们使用shell，创建一个进程。&amp;nbsp;&amp;lt;br&amp;gt;这个进程，也属于自己的进程组，&amp;nbsp;当前的进程组id就是进程自己的id。&amp;nbsp;&amp;lt;br&amp;gt;后续，我们在这个进程中，通过fork创建出来的子进程，属于父进程的组。&amp;lt;br&amp;gt;"><node CREATED="1747229453204" ID="ID_117c25b20b10b8f9" MODIFIED="1747229453204" TEXT="getpgrp()获取组id"></node><node CREATED="1747229453204" ID="ID_3410f5fddc40bba6" MODIFIED="1747229453204" TEXT="setpgid()&amp;nbsp;脱离当前这个组&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229453204" ID="ID_d6164d23d647e14e" MODIFIED="1747229453204" TEXT="当一个shell会话被关掉的时候。前台进程组会被干掉，后台进程会收到信号，也会退掉。&amp;nbsp;"><node CREATED="1747229453204" ID="ID_6eccdeaaa05e8d69" MODIFIED="1747229453204" TEXT="如果说，后续，想启动一个进程。&amp;nbsp;保持这个进程一直活着。&amp;lt;br&amp;gt;不光要fork，还要让它脱离一下当前的会话。&amp;nbsp; setsid()&amp;lt;br&amp;gt;脱离了会话之后，&amp;nbsp;即使老的会话被干掉。&amp;nbsp;这个脱离出来的进程不会被干掉"></node></node><node CREATED="1747229453204" ID="ID_d7593efea3203b95" MODIFIED="1747229453204" TEXT="会话简单说，就是一些进程组的集合。&amp;nbsp;只有一个前台进程组，多个后台进程组。&amp;nbsp;&amp;lt;br&amp;gt;当会话退掉的时候，相关的进程组都会退掉。&amp;nbsp;"></node></node><node CREATED="1747229453204" ID="ID_8fcf16693b307022" MODIFIED="1747229453204" TEXT="守护进程"><node CREATED="1747229453204" ID="ID_587df96dc03cbb3a" MODIFIED="1747229453204" TEXT="就是在后台一直运行的进程。&amp;nbsp;用于执行一些特定的任务。&amp;nbsp;"></node><node CREATED="1747229453204" ID="ID_14ee0996e14e39c6" MODIFIED="1747229453204" TEXT="比如在有一些电脑上，会有一些程序在后台手机，CPU目前的状态，内存的状态，磁盘的状态。&amp;nbsp;最后将这些信息全部都记录下来，&amp;lt;br&amp;gt;下一次电脑出了问题，想分析和CPU的关系。"></node><node CREATED="1747229453204" ID="ID_67cf4ce6f39d6d3d" MODIFIED="1747229453204" TEXT="创建守护进程的时候，一定让其脱离会话，不然终端关，这个进程也会被干掉。"></node></node><node CREATED="1747229453204" ID="ID_f6789710415058c3" MODIFIED="1747229453204" TEXT="守护进程的标准输入，标准输出，标准错误流都关了。它怎么向外表示自己的一些状态，比如出现了某些问题。"><node CREATED="1747229453204" ID="ID_b7c54bcdd0705b93" MODIFIED="1747229453204" TEXT="写到文件里"></node><node CREATED="1747229453204" ID="ID_13d0bb80d2da88c2" MODIFIED="1747229453204" TEXT="其实就是将之前的标准输出，弄到文件里存着。 （重定向）"></node><node CREATED="1747229453204" ID="ID_c9859508f9ea9e16" MODIFIED="1747229453204" TEXT="日志：其实就是将一些打印弄到文件里。&amp;nbsp;如果在公司中，所有的信息都是打印在控制台上，&amp;nbsp;如果电脑突然挂了。&amp;lt;br&amp;gt;这时候，其实看不到之前的打印。&amp;nbsp;所以，我们一个更稳妥的方式就是打印在文件中。&amp;nbsp;&amp;nbsp;"></node><node CREATED="1747229453204" ID="ID_d1aaf7519bb9b3d9" MODIFIED="1747229453204" TEXT="这块的关键不是syslog。而是大家要知道日志是什么东西，&amp;lt;br&amp;gt;日志有什么好处。&amp;nbsp;日志的基本使用。&amp;nbsp;&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;"><node CREATED="1747229453204" ID="ID_07e71e58375d451a" MODIFIED="1747229453204" TEXT="日志还有一个好处就是可以分级输出。&amp;nbsp;&amp;lt;br&amp;gt;甚至还可以直接不输出"></node><node CREATED="1747229453204" ID="ID_118ef84badf61be6" MODIFIED="1747229453204" TEXT="可以设置不同的级别，让日志&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;[DEBUG]&amp;nbsp;时间&amp;nbsp;地点&amp;nbsp;事件&amp;nbsp;关键信息&amp;lt;br&amp;gt;[INFO] 时间 地点 事件 关键信息&amp;lt;br&amp;gt;[WARNNING] 时间 地点 事件 关键信息&amp;lt;br&amp;gt;[ERROR] 时间 地点 事件 关键信息&amp;lt;br&amp;gt;"><node CREATED="1747229453204" ID="ID_7a185c8977eb4f7c" MODIFIED="1747229453204" TEXT="grep &amp;quot;ERROR&amp;quot;"></node><node CREATED="1747229453204" ID="ID_63f322001f1245c2" MODIFIED="1747229453204" TEXT="if(current_priority &amp;gt; NEED_LOG_PROORITY ){&amp;lt;br&amp;gt;&amp;nbsp; &amp;nbsp;printf(&amp;quot;日志文件中输出&amp;quot;)；&amp;lt;br&amp;gt;}"></node></node><node CREATED="1747229453204" ID="ID_dd16efaf64fb1848" MODIFIED="1747229453204" TEXT="日志级别一般用来做日志的筛选输出。&amp;lt;br&amp;gt;条件编译。&amp;nbsp;可以通过更细颗粒的日志级别，来控制有一些日志输出，有一些不输出。&amp;nbsp;&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;&amp;nbsp;#if priority &amp;gt; DEBUG:&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229453204" ID="ID_3bec0d21115a6bfc" MODIFIED="1747229453204" TEXT="线上环境=生产环境"></node></node></node></node></node></map>